<!doctype html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>{{ $competition->tournament->name }} · Desarrollo</title>
    <style>
        :root{color-scheme:light dark;--navy:#173d7c;--blue:#2464ce;--green:#07844d;--gold:#e4a900;--ink:#17253a;--muted:#65758b;--line:#d8e0ea;--surface:#fff;--soft:#f4f7fb;--page:#edf2f7}*{box-sizing:border-box}body{margin:0;background:var(--page);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.hero{padding:20px clamp(16px,4vw,54px);color:#fff;background:linear-gradient(105deg,#18336d,#185381 65%,#078476);border-bottom:4px solid var(--gold)}.hero small{color:#ffe38b;font-weight:900;letter-spacing:.14em}.hero h1{margin:5px 0 3px;font-size:clamp(22px,4vw,38px)}.hero p{margin:0;color:#dceaff}.wrap{max-width:1500px;margin:auto;padding:18px clamp(10px,3vw,34px)}.tabs{display:flex;gap:7px;overflow:auto;padding:5px;background:var(--surface);border:1px solid var(--line);border-radius:14px}.tab{border:0;border-radius:10px;padding:10px 14px;background:transparent;color:var(--muted);white-space:nowrap;font-weight:800;cursor:pointer}.tab.on{background:var(--navy);color:#fff}.panel{display:none;padding-top:15px}.panel.on{display:block}.phase-head{display:flex;justify-content:space-between;gap:12px;align-items:end;margin-bottom:12px}.phase-head h2{margin:0}.badge{padding:6px 10px;border-radius:999px;background:#e4f7ed;color:var(--green);font-size:11px;font-weight:900}.slots{display:flex;gap:6px;overflow:auto;margin-bottom:12px}.slot{border:1px solid var(--line);border-radius:999px;background:var(--surface);padding:7px 11px;white-space:nowrap;cursor:pointer}.slot.on{color:var(--blue);border-color:var(--blue);background:#eaf2ff}.zones{display:grid;gap:14px}.zone{background:var(--surface);border:1px solid var(--line);border-radius:12px;overflow:hidden}.zone-title{display:flex;justify-content:space-between;gap:10px;background:var(--navy);color:#fff;padding:9px 12px;font-weight:900}.zone-body{display:grid;grid-template-columns:1.2fr .8fr;gap:12px;padding:12px}.matches{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:8px}.match{border:1px solid var(--line);border-left:4px solid var(--blue);border-radius:8px;padding:7px;background:var(--soft);font-size:11px}.match b{display:block;margin-bottom:5px;color:var(--navy)}.line{display:flex;justify-content:space-between;gap:8px;padding:3px 0}.winner{color:var(--green);font-weight:900}.standings{width:100%;border-collapse:collapse;font-size:11px}.standings th{background:var(--green);color:#fff}.standings th,.standings td{padding:7px;border:1px solid var(--line);text-align:center}.standings td:nth-child(2){text-align:left;font-weight:800}.scroll{overflow:auto}.bracket{display:grid;gap:13px;min-width:920px}.round{display:flex;flex-direction:column;justify-content:space-around;gap:9px}.round h3{text-align:center;margin:0 0 7px;padding:7px;background:var(--navy);color:#fff;border-radius:7px;font-size:11px}.empty{padding:35px;text-align:center;border:1px dashed var(--line);border-radius:12px;background:var(--surface)}.error{color:#b42318}footer{margin-top:24px;padding:14px 0;border-top:2px solid var(--navy);display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:11px}@media(prefers-color-scheme:dark){:root{--ink:#eef4ff;--muted:#9dadc2;--line:#2b3950;--surface:#111a28;--soft:#182334;--page:#09111d}}@media(max-width:760px){.zone-body{grid-template-columns:1fr}.matches{grid-template-columns:1fr}.phase-head,footer{align-items:flex-start;flex-direction:column}.standings{min-width:580px}}
    </style>
</head>
<body>
<header class="hero"><small>FEDERACIÓN ARGENTINA DE BILLAR</small><h1>{{ $competition->tournament->name }}</h1><p>Desarrollo y resultados en tiempo real</p></header>
<main class="wrap"><nav class="tabs" id="tabs"></nav><div id="content"><div class="empty">Cargando competencia…</div></div><footer><strong>Federación Argentina de Billar</strong><span>Información oficial del torneo</span></footer></main>
<script>
const endpoint=@json($jsonUrl);let data=null;
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const stateLabel=s=>({pending:'Pendiente',ready:'Preparada',in_progress:'En curso',completed:'Finalizada'}[s]||s);
function score(m,i){return Array.isArray(m.sets_computables)?m.sets_computables[i]:'—'}
function matchCard(m){return `<article class="match"><b>${esc(m.etiqueta)}</b><div class="line ${m.ganador===m.jugador_1?'winner':''}"><span>${esc(m.jugador_1)}</span><span>${esc(score(m,0))}</span></div><div class="line ${m.ganador===m.jugador_2?'winner':''}"><span>${esc(m.jugador_2)}</span><span>${esc(score(m,1))}</span></div>${m.horario?`<small>${new Date(m.horario).toLocaleString('es-AR')} · Mesa ${esc(m.mesa)}</small>`:''}</article>`}
function zones(phase){const slots=[...new Set(phase.zonas.map(z=>z.horario||'SIN HORARIO'))];const nav=slots.map((s,i)=>`<button class="slot ${i?'':'on'}" data-slot="${esc(s)}">${esc(s)}</button>`).join('');return `<div class="slots">${nav}</div><div class="zones" id="zones">${zoneCards(phase,slots[0])}</div>`}
function zoneCards(phase,slot){return phase.zonas.filter(z=>(z.horario||'SIN HORARIO')===slot).map(z=>{const ms=phase.partidos.filter(m=>m.zona_id===z.id);return `<section class="zone"><div class="zone-title"><span>${esc(z.nombre)}</span><span>${esc(z.horario)}</span></div><div class="zone-body"><div class="matches">${ms.map(matchCard).join('')}</div><div class="scroll"><table class="standings"><thead><tr><th>Pos</th><th>Jugador</th><th>PG</th><th>DS</th><th>PF</th><th>PC</th><th>Prom</th></tr></thead><tbody>${z.jugadores.slice().sort((a,b)=>(a.clasificacion||99)-(b.clasificacion||99)).map(p=>`<tr><td>${esc(p.clasificacion)}</td><td>${esc(p.nombre)}</td><td>${esc(p.partidos_ganados)}</td><td>${esc(p.diferencia_sets)}</td><td>${esc(p.puntos_favor)}</td><td>${esc(p.puntos_contra)}</td><td>${esc(p.promedio)}</td></tr>`).join('')}</tbody></table></div></div></section>`}).join('')||'<div class="empty">Todavía no hay zonas publicadas para este horario.</div>'}
function bracket(phase){const rounds=Object.groupBy?Object.groupBy(phase.partidos,m=>m.ronda):phase.partidos.reduce((a,m)=>((a[m.ronda]??=[]).push(m),a),{});const keys=Object.keys(rounds).sort((a,b)=>a-b);return `<div class="scroll"><div class="bracket" style="grid-template-columns:repeat(${Math.max(keys.length,1)},minmax(190px,1fr))">${keys.map(k=>`<section class="round"><h3>Ronda ${k}</h3>${rounds[k].sort((a,b)=>a.orden-b.orden).map(matchCard).join('')}</section>`).join('')}</div></div>`}
function render(index){const phase=data.fases[index];document.querySelectorAll('.tab').forEach((b,i)=>b.classList.toggle('on',i===index));document.querySelector('#content').innerHTML=`<section class="panel on"><div class="phase-head"><div><h2>${esc(phase.nombre)}</h2><small>${phase.sets} sets · ${phase.puntos_por_set} puntos</small></div><span class="badge">${esc(stateLabel(phase.estado))}</span></div>${phase.tipo==='zones'?zones(phase):bracket(phase)}</section>`;document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-slot]').forEach(x=>x.classList.toggle('on',x===b));document.querySelector('#zones').innerHTML=zoneCards(phase,b.dataset.slot)})}
fetch(endpoint,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('No fue posible obtener los resultados');return r.json()}).then(r=>{data=r.data;document.querySelector('#tabs').innerHTML=data.fases.map((p,i)=>`<button class="tab ${i?'':'on'}" data-i="${i}">${i+1}. ${esc(p.nombre)}</button>`).join('');document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>render(Number(b.dataset.i)));render(0)}).catch(e=>document.querySelector('#content').innerHTML=`<div class="empty error">${esc(e.message)}</div>`);
</script>
</body></html>
